'use client';

import { useState } from 'react';
import Image from 'next/image';

interface GalleryImage {
  id: number;
  src: string;
  alt: string;
  edition: number;
}

// Images des éditions
const generateGalleryImages = (): GalleryImage[] => {
  return [
    // Édition 14 (2025-2026)
    {
      id: 1,
      src: '/images/editions/edition14-1.jpeg',
      alt: 'Édition 2025-2026 - Page 1',
      edition: 14
    },
    {
      id: 2,
      src: '/images/editions/edition14-2.jpeg',
      alt: 'Édition 2025-2026 - Page 2',
      edition: 14
    },
    {
      id: 3,
      src: '/images/editions/edition14-3.jpeg',
      alt: 'Édition 2025-2026 - Page 3',
      edition: 14
    }
  ];
};

export default function GallerySection() {
  const TOTAL_EDITIONS = 14;
  const [selectedEdition, setSelectedEdition] = useState<number>(TOTAL_EDITIONS); // Dernière édition par défaut
  const [selectedImage, setSelectedImage] = useState<GalleryImage | null>(null);
  const [showAllEditions, setShowAllEditions] = useState(false);
  
  const allImages = generateGalleryImages();
  
  const filteredImages = allImages.filter(img => img.edition === selectedEdition);
  const allEditionsImages = showAllEditions ? allImages : [];
  
  const editions = Array.from({ length: TOTAL_EDITIONS }, (_, i) => i + 1);
  
  // Afficher uniquement la dernière édition par défaut
  const recentEditions = [14]; // Affiche uniquement l'édition 14 (2025-2026)

  // Fonction pour afficher toutes les éditions
  const toggleAllEditions = () => {
    setShowAllEditions(prev => !prev);
  };

  return (
    <section className="py-16 md:py-24 bg-background">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12 max-w-3xl mx-auto">
          <span className="inline-block text-primary font-bold text-sm uppercase tracking-[0.2em] mb-4">
            Galeries Photos
          </span>
          <h2 className="text-3xl md:text-4xl lg:text-5xl font-bold text-foreground mb-6 leading-tight">
            Nos <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary to-accent">Éditions</span>
          </h2>
          <div className="w-20 h-1 bg-gradient-to-r from-primary to-accent mx-auto mb-8 rounded-full"></div>
          <p className="text-foreground/80 text-lg md:text-xl leading-relaxed font-medium">
            Revivez les moments forts de nos 14 éditions de formation
          </p>
        </div>

        {/* En-tête de la galerie */}
        <div className="text-center mb-12 max-w-4xl mx-auto">
          <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-4">
            Galerie des <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary to-accent">Éditions</span>
          </h2>
          <p className="text-foreground/80 text-lg mb-8 max-w-2xl mx-auto">
            Découvrez les moments forts de nos éditions passées
          </p>
          
          <div className="flex flex-wrap justify-center items-center gap-4 mb-8">
            <div className="relative group">
              <button
                onClick={toggleAllEditions}
                className={`px-6 py-3 rounded-xl font-medium transition-all duration-300 ${
                  showAllEditions
                    ? 'bg-gradient-to-r from-primary to-accent text-white shadow-lg shadow-primary/30'
                    : 'bg-white/5 hover:bg-white/10 text-foreground border border-white/10 hover:border-primary/30'
                }`}
              >
                {showAllEditions ? 'Voir moins' : 'Voir toutes les éditions'}
              </button>
              <div className="absolute -bottom-2 left-0 right-0 h-1 bg-gradient-to-r from-primary to-accent opacity-0 group-hover:opacity-100 transition-opacity"></div>
            </div>
            
            <div className="relative group">
              <div className="flex items-center bg-white/5 hover:bg-white/10 border border-white/10 hover:border-primary/30 rounded-xl px-4 py-3 cursor-pointer transition-all duration-300">
                <span className="mr-2 text-foreground/80">Édition:</span>
                <select 
                  value={selectedEdition}
                  onChange={(e) => setSelectedEdition(Number(e.target.value))}
                  className="bg-transparent border-none focus:ring-0 text-foreground cursor-pointer"
                >
                  {editions.map((edition) => (
                    <option key={edition} value={edition} className="bg-background text-foreground">
                      Édition {edition}
                      {edition === TOTAL_EDITIONS && ' (Dernière)'}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          </div>
        </div>

        {/* Instructions pour l'ajout d'images */}
        <div className="bg-gradient-to-r from-blue-50 to-blue-100 dark:from-blue-900/20 dark:to-blue-800/10 p-6 rounded-xl mb-8 border border-blue-200 dark:border-blue-800 shadow-sm">
          <div className="text-center space-y-6">
            <h3 className="text-2xl font-bold text-blue-800 dark:text-blue-100">
              🌍 Allez dans tout le monde entier et proclamez la Bonne Nouvelle à toute la création ! 🌍
            </h3>
            <p className="text-blue-700 dark:text-blue-300 italic text-lg">
              « Allez dans le monde entier, proclamez l'Évangile à toute la création. » - Marc 16:15
            </p>
            
            <div className="max-w-2xl mx-auto bg-white/80 dark:bg-blue-900/30 p-6 rounded-xl border border-blue-100 dark:border-blue-700 shadow-sm">
              <h4 className="text-xl font-semibold text-blue-800 dark:text-blue-200 mb-3">Partagez votre lumière avec le monde</h4>
              <p className="text-blue-700 dark:text-blue-300">
                Témoignez de la gloire de Dieu en partageant vos moments de grâce et de louange avec nos frères et sœurs du monde entier.
              </p>
            </div>
          </div>
        </div>

        {/* Galerie d'images */}
        <div className="space-y-12">
          {/* Édition sélectionnée */}
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <h3 className="text-2xl font-bold text-foreground">
                Édition {selectedEdition}
                {selectedEdition === TOTAL_EDITIONS && ' (Dernière édition)'}
              </h3>
              <span className="px-3 py-1 bg-primary/10 text-primary text-sm font-medium rounded-full">
                {filteredImages.length} photos
              </span>
            </div>
            
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredImages.length > 0 ? (
                filteredImages.map((image) => (
                    <div 
                      key={image.id} 
                      className="group relative overflow-hidden rounded-2xl aspect-square cursor-pointer transform transition-all duration-300 hover:scale-[1.02] hover:shadow-xl"
                      onClick={() => setSelectedImage(image)}
                    >
                      <div className="absolute inset-0 bg-gradient-to-t from-black/70 to-transparent opacity-0 group-hover:opacity-100 transition-opacity z-10 flex flex-col justify-between p-5">
                        <div className="flex justify-end">
                          <span className="px-3 py-1 bg-black/50 backdrop-blur-sm text-white text-xs font-medium rounded-full">
                            Édition {image.edition}
                          </span>
                        </div>
                        <div className="transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300">
                          <p className="text-white font-medium text-lg mb-1">Édition {image.edition}</p>
                          <p className="text-white/80 text-sm">Photo {image.id % 3 || 3}</p>
                        </div>
                      </div>
                      <div className="absolute inset-0 bg-gradient-to-b from-transparent via-black/10 to-black/30 group-hover:bg-black/40 transition-all duration-300 z-0"></div>
                      <div className="relative w-full h-full">
                        <Image
                          src={image.src}
                          alt={image.alt}
                          fill
                          className="object-cover"
                          placeholder="blur"
                          blurDataURL="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="
                        />
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="col-span-full text-center py-12">
                    <div className="mx-auto w-16 h-16 bg-white/5 rounded-full flex items-center justify-center mb-4">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-foreground/30" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                      </svg>
                    </div>
                    <p className="text-foreground/60">Aucune photo disponible pour cette édition</p>
                  </div>
                )}
            </div>
          </div>
          
          {/* Toutes les éditions (si activé) */}
          {showAllEditions && (
            <div className="space-y-6">
              <h3 className="text-2xl font-bold text-foreground">Toutes les éditions</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {allEditionsImages.map((image) => (
                  <div 
                    key={image.id} 
                    className="group relative overflow-hidden rounded-2xl aspect-square cursor-pointer transform transition-all duration-300 hover:scale-[1.02] hover:shadow-xl"
                    onClick={() => setSelectedImage(image)}
                  >
                    <div className="absolute inset-0 bg-gradient-to-t from-black/70 to-transparent opacity-0 group-hover:opacity-100 transition-opacity z-10 flex flex-col justify-between p-5">
                      <div className="flex justify-end">
                        <span className="px-3 py-1 bg-black/50 backdrop-blur-sm text-white text-xs font-medium rounded-full">
                          Édition {image.edition}
                        </span>
                      </div>
                      <div className="transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300">
                        <p className="text-white font-medium text-lg mb-1">Édition {image.edition}</p>
                        <p className="text-white/80 text-sm">Photo {image.id % 3 || 3}</p>
                      </div>
                    </div>
                    <div className="absolute inset-0 bg-gradient-to-b from-transparent via-black/10 to-black/30 group-hover:bg-black/40 transition-all duration-300 z-0"></div>
                    <div className="relative w-full h-full">
                      <Image
                        src={image.src}
                        alt={image.alt}
                        fill
                        className="object-cover"
                        placeholder="blur"
                        blurDataURL="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Modal pour l'image sélectionnée */}
          {selectedImage && (
          <div 
            className="fixed inset-0 bg-black/90 z-50 flex items-center justify-center p-4"
            onClick={() => setSelectedImage(null)}
          >
            <div className="relative w-full max-w-4xl max-h-[90vh]">
              <button 
                className="absolute -top-10 right-0 text-white hover:text-primary transition-colors"
                onClick={(e) => {
                  e.stopPropagation();
                  setSelectedImage(null);
                }}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
              <div className="relative w-full h-0 pb-[75%] bg-gray-800 rounded-lg overflow-hidden">
                <Image
                  src={selectedImage.src}
                  alt={selectedImage.alt}
                  fill
                  className="object-contain"
                  placeholder="blur"
                  blurDataURL="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="
                />
              </div>
              <div className="mt-4 text-center text-white">
                <p className="text-lg font-medium">Édition {selectedImage.edition}</p>
                <p className="text-white/70">Photo {selectedImage.id % 3 || 3}</p>
              </div>
            </div>
          </div>
          )}
        </div>
      </div>
    </section>
  );
}
